/*
 * Method: field_download
 * 
 * Generate the template for a simple download button.
 * 
 * Arguments:
 *  label - the text to use for the hover
 *  count - the number of items to download
 *  fields - the field to download
 * 
 * Returns:
 *  hash form of jQuery button template for consumption by <search_pane>.
 */
bbop.widget.display.button_templates.field_download = function (label, count, fields) {
  var dl_props = {
    'entity_list': null,
    'rows': count
  };
  var field_download_button = {
    label: label,
    diabled_p: false,
    // text_p: false,
    // icon: 'ui-icon-document',
    click_function_generator: function (manager, results_table) {
      return function (event) {
        var dialog_props = {
          title: 'Download',
          buttons: {
            'Download': function () {
              //alert('download');
              dl_props['entity_list'] = results_table.get_selected_items();
              var raw_gdl = manager.get_download_url(fields, dl_props);
              window.open(raw_gdl, '_blank');
              //jQuery(this).dialog('destroy');
              jQuery(this).remove();
            },
            'Cancel': function () {
              //jQuery(this).dialog('destroy');
              jQuery(this).remove();
            }
          }
        };
        new bbop.widget.dialog('<h4>Download (up to ' + count + ')</h4><p>You may download up to ' + count + ' lines in a new window. If your request is large or if the the server busy, this may take a while to complete--please be patient.</p>', dialog_props);
        //window.open(raw_gdl, '_blank');
      };
    }
  };
  return field_download_button;
};

