      box_spacing: 10,
      // space between leaf box edge and leaf label
      leaf_padding: 4,
      // leaf border thickness
      leaf_border: 2,
      // leaf left offset
      leaf_margin: 1,
      // width/height of internal nodes
      node_size: 8,
      // leaf border color
      leaf_border_color: "blue",
      // font for leaf labels
      leaf_font: "Helvetica, Arial, sans-serif",
